IF DB_ID(N'GarageDB') IS NULL CREATE DATABASE GarageDB;
GO
USE GarageDB;
GO
IF OBJECT_ID(N'dbo.KhachHang',N'U') IS NULL CREATE TABLE dbo.KhachHang(MaKH INT IDENTITY(1,1) PRIMARY KEY,TenKH NVARCHAR(100) NOT NULL,DienThoai VARCHAR(15) NOT NULL UNIQUE,DiaChi NVARCHAR(200) NULL);
IF OBJECT_ID(N'dbo.Xe',N'U') IS NULL CREATE TABLE dbo.Xe(BienSo VARCHAR(20) PRIMARY KEY,MaKH INT NOT NULL REFERENCES dbo.KhachHang(MaKH),HieuXe NVARCHAR(50) NOT NULL,NamSanXuat INT NULL);
IF OBJECT_ID(N'dbo.PhuTung',N'U') IS NULL CREATE TABLE dbo.PhuTung(MaPhuTung INT IDENTITY(1,1) PRIMARY KEY,TenPhuTung NVARCHAR(150) NOT NULL,DonGia DECIMAL(18,2) NOT NULL CHECK(DonGia>=0),SoLuongTon INT NOT NULL CHECK(SoLuongTon>=0));
IF OBJECT_ID(N'dbo.PhieuSuaChua',N'U') IS NULL CREATE TABLE dbo.PhieuSuaChua(MaPhieu INT IDENTITY(1,1) PRIMARY KEY,BienSo VARCHAR(20) NOT NULL REFERENCES dbo.Xe(BienSo),NgayNhan DATETIME NOT NULL CONSTRAINT DF_Phieu_Ngay DEFAULT GETDATE(),NoiDungSua NVARCHAR(MAX) NULL,TongTien DECIMAL(18,2) NOT NULL CONSTRAINT DF_Phieu_Tong DEFAULT 0,TrangThai NVARCHAR(30) NOT NULL CONSTRAINT DF_Phieu_Status DEFAULT N'Đang sửa');
IF OBJECT_ID(N'dbo.ChiTietSuaChua',N'U') IS NULL CREATE TABLE dbo.ChiTietSuaChua(MaPhieu INT NOT NULL REFERENCES dbo.PhieuSuaChua(MaPhieu),MaPhuTung INT NOT NULL REFERENCES dbo.PhuTung(MaPhuTung),SoLuong INT NOT NULL CHECK(SoLuong>0),TienCong DECIMAL(18,2) NOT NULL CONSTRAINT DF_ChiTiet_TienCong DEFAULT 0,DonGia DECIMAL(18,2) NOT NULL CONSTRAINT DF_ChiTiet_DonGia DEFAULT 0,CONSTRAINT PK_ChiTietSuaChua PRIMARY KEY(MaPhieu,MaPhuTung));
IF NOT EXISTS(SELECT 1 FROM dbo.KhachHang) INSERT dbo.KhachHang(TenKH,DienThoai,DiaChi) VALUES(N'Nguyễn Văn An','0901000001',N'Quận 1, TP. Hồ Chí Minh'),(N'Trần Thị Mai','0901000002',N'Thủ Đức, TP. Hồ Chí Minh');
IF NOT EXISTS(SELECT 1 FROM dbo.Xe) INSERT dbo.Xe(BienSo,MaKH,HieuXe,NamSanXuat) SELECT '51A-123.45',MaKH,N'Toyota',2021 FROM dbo.KhachHang WHERE DienThoai='0901000001' UNION ALL SELECT '51H-678.90',MaKH,N'VinFast',2023 FROM dbo.KhachHang WHERE DienThoai='0901000002';
IF NOT EXISTS(SELECT 1 FROM dbo.PhuTung) INSERT dbo.PhuTung(TenPhuTung,DonGia,SoLuongTon) VALUES(N'Lọc nhớt động cơ',180000,18),(N'Bugi đánh lửa',95000,24),(N'Dầu động cơ 4L',620000,9),(N'Bộ lọc gió',240000,12);
